import { cn } from "@/lib/utils";

export function PageHeader({
  title,
  description,
  className,
}: {
  title: string;
  description?: string;
  className?: string;
}) {
  return (
    <div className={cn("mb-8", className)}>
      <h1 className="text-2xl font-bold text-p-green sm:text-3xl">{title}</h1>
      <div className="mt-2 h-1 w-16 rounded-full bg-p-red" />
      {description && (
        <p className="mt-3 text-base leading-relaxed text-p-black/78">{description}</p>
      )}
    </div>
  );
}

export function PageBusy({
  title,
  description,
}: {
  title: string;
  description?: string;
}) {
  return (
    <div>
      <PageHeader title={title} description={description} className="mb-4" />
      <div className="space-y-3">
        <div className="h-24 animate-pulse rounded-2xl bg-neutral-100" />
        <div className="h-24 animate-pulse rounded-2xl bg-neutral-100" />
      </div>
    </div>
  );
}
